    // MILESTONES
    // ══════════════════════════════════════════════════════════════
    async function loadMilestones() {
        if (!state.currentProject) return;
        try {
            const data = await api('/projects/' + state.currentProject.id + '/milestones');
            state.milestones = data.milestones || [];
            const el = document.getElementById('milestoneTimeline');
            if (state.milestones.length === 0) {
                el.innerHTML = '<p class="text-sm text-muted">No milestones.</p>';
            } else {
                el.innerHTML = state.milestones.map(m => `
                    <div class="milestone-node ${m.status}">
                        <div class="flex-between">
                            <div>
                                <span style="font-size:13px;font-weight:600;">${esc(m.title)}</span>
                                <span class="badge ${m.phase}" style="margin-left:8px;">${esc(m.phase)}</span>
                                <span class="badge ${m.status}" style="margin-left:4px;">${m.status}</span>
                            </div>
                            <button class="btn btn-secondary btn-sm" onclick="showEditMilestone('${m.id}')">Edit</button>
                        </div>
                        ${m.description ? '<p class="text-sm text-muted" style="margin-top:4px;">' + esc(m.description) + '</p>' : ''}
                        <div class="milestone-progress"><div class="milestone-progress-fill" style="width:${m.completion_pct || 0}%;"></div></div>
                        <div style="display:flex;gap:12px;font-size:10px;color:var(--gl-text-muted);margin-top:4px;">
                            <span>${m.completion_pct || 0}% complete</span>
                            ${m.target_date ? '<span>Target: ' + m.target_date + '</span>' : ''}
                            ${m.actual_date ? '<span>Actual: ' + m.actual_date + '</span>' : ''}
                        </div>
                    </div>`).join('');
            }
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function createMilestone() {
        if (!state.currentProject) return;
        const data = getModalData('milestoneModal');
        if (!data.title) return;
        try {
            await api('/projects/' + state.currentProject.id + '/milestones', { method: 'POST', body: JSON.stringify(data) });
            closeModal('milestoneModal');
            clearModal('milestoneModal');
            loadMilestones();
            setStatus('Milestone created');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function showEditMilestone(id) {
        const m = state.milestones.find(x => x.id === id);
        if (!m) return;
        document.getElementById('editMilestoneId').value = id;
        setModalData('editMilestoneModal', m);
        showModal('editMilestoneModal');
    }

    async function updateMilestone() {
        const id = document.getElementById('editMilestoneId').value;
        if (!id || !state.currentProject) return;
        const data = getModalData('editMilestoneModal');
        try {
            await api('/projects/' + state.currentProject.id + '/milestones/' + id, { method: 'PUT', body: JSON.stringify(data) });
            closeModal('editMilestoneModal');
            loadMilestones();
            setStatus('Milestone updated');
        } catch (err) { setStatus('Error: ' + err.message); }
    }
